import os
import sys
import shutil
import urllib.request
import subprocess
from datetime import datetime
import time

LOG_FILE = "notification_log.txt"
SANDBOX_DIR = "./sandbox"
DEFAULT_ITERATIONS = 1
DEFAULT_INTERVAL = 10  # seconds

def fetch_url_content(url):
    try:
        with urllib.request.urlopen(url) as response:
            return response.read().decode("utf-8")
    except Exception as e:
        log_error(f"Error fetching URL content: {e}")
        sys.exit(1)

def log_content(content):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] {content}\n")
    except Exception as e:
        log_error(f"Error writing to log file: {e}")
        sys.exit(1)

def log_error(message):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] ERROR: {message}\n")
    except:
        print(f"Critical error: {message}", file=sys.stderr)

def copy_to_sandbox():
    try:
        os.makedirs(SANDBOX_DIR, exist_ok=True)
        target_path = os.path.join(SANDBOX_DIR, os.path.basename(__file__))
        if not os.path.exists(target_path):
            shutil.copy(__file__, target_path)
    except Exception as e:
        log_error(f"Error copying file to sandbox: {e}")
        sys.exit(1)

def run_as_background_process():
    try:
        subprocess.Popen([sys.executable, __file__, "--background"])
    except Exception as e:
        log_error(f"Error starting background process: {e}")

def main():
    if "--background" in sys.argv:
        # Simulate a background process
        url = os.getenv("FETCH_URL")
        iterations = int(os.getenv("FETCH_ITERATIONS", DEFAULT_ITERATIONS))
        interval = float(os.getenv("FETCH_INTERVAL", DEFAULT_INTERVAL))
        if not url:
            log_error("FETCH_URL environment variable not set.")
            sys.exit(1)

        for _ in range(iterations):
            content = fetch_url_content(url)
            log_content(content)
            time.sleep(interval)
        sys.exit(0)

    if len(sys.argv) < 2:
        print("Usage: python fetch_url.py <URL> [iterations] [interval]", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    iterations = int(sys.argv[2]) if len(sys.argv) > 2 else DEFAULT_ITERATIONS
    interval = float(sys.argv[3]) if len(sys.argv) > 3 else DEFAULT_INTERVAL

    copy_to_sandbox()
    os.environ["FETCH_URL"] = url
    os.environ["FETCH_ITERATIONS"] = str(iterations)
    os.environ["FETCH_INTERVAL"] = str(interval)

    run_as_background_process()

if __name__ == "__main__":
