import os
import sys
import time
import ftplib
import argparse
from functools import wraps

class SocialMediaActivityMonitor:
    def __init__(self, log_dir='./target', ftp_config=None, interval=60, iterations=1):
        self.log_dir = log_dir
        self.ftp_config = ftp_config
        self.interval = interval
        self.iterations = iterations
        self.running = False
        self.activities = {
            "posts": ["Post 1", "Post 2", "Post 3"],
            "messages": ["Message 1", "Message 2"],
            "interactions": ["Like 1", "Comment 1"]
        }

    def start(self):
        self.running = True
        self.log("Tool has started.")
        self.prepare_log_directory()
        self.run()

    def run(self):
        for _ in range(self.iterations):
            try:
                self.log("Capturing activities...")
                self.capture_activities()
                if self.ftp_config:
                    self.log("Uploading log files to FTP server...")
                    self.upload_logs_to_ftp()
                self.log("Cycle completed.")
                if self.iterations > 1:
                    time.sleep(self.interval)
            except Exception as e:
                self.log(f"Error encountered: {e}")
        self.stop()

    def stop(self):
        self.running = False
        self.log("Execution completed. Exiting cleanly.")
        sys.exit(0)

    def prepare_log_directory(self):
        try:
            if not os.path.exists(self.log_dir):
                os.makedirs(self.log_dir)
                self.log(f"Created log directory: {self.log_dir}")
        except Exception as e:
            self.log(f"Failed to create log directory: {e}")
            sys.exit(1)

    def capture_activities(self):
        for activity_type, activity_list in self.activities.items():
            log_file = os.path.join(self.log_dir, f"{activity_type}.log")
            try:
                with open(log_file, 'w') as file:
                    file.write(f"Captured {activity_type}:\n")
                    for activity in activity_list:
                        file.write(f"- {activity}\n")
                self.log(f"Saved {activity_type} data to {log_file}")
            except Exception as e:
                self.log(f"Failed to write {activity_type} log file: {e}")

    def upload_logs_to_ftp(self):
        try:
            with ftplib.FTP(self.ftp_config["host"]) as ftp:
                ftp.login(self.ftp_config["user"], self.ftp_config["password"])
                ftp.cwd(self.ftp_config.get("directory", "/"))
                for file_name in os.listdir(self.log_dir):
                    file_path = os.path.join(self.log_dir, file_name)
                    with open(file_path, 'rb') as file:
                        ftp.storbinary(f"STOR {file_name}", file)
                    self.log(f"Uploaded {file_name} to FTP server.")
        except Exception as e:
            self.log(f"Failed to upload files to FTP server: {e}")

    @staticmethod
    def log(message):
        print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {message}")

def parse_arguments():
    parser = argparse.ArgumentParser(description="Social Media Activity Monitoring Tool")
    parser.add_argument("--log-dir", type=str, default="./target", help="Directory to save log files")
    parser.add_argument("--ftp-host", type=str, help="FTP server host")
    parser.add_argument("--ftp-user", type=str, help="FTP server username")
    parser.add_argument("--ftp-password", type=str, help="FTP server password")
    parser.add_argument("--ftp-directory", type=str, default="/", help="FTP server directory")
    parser.add_argument("--interval", type=int, default=60, help="Interval between iterations in seconds")
    parser.add_argument("--iterations", type=int, default=1, help="Number of iterations to run")
    return parser.parse_args()

def main():
    args = parse_arguments()
    ftp_config = None
    if args.ftp_host and args.ftp_user and args.ftp_password:
        ftp_config = {
            "host": args.ftp_host,
            "user": args.ftp_user,
            "password": args.ftp_password,
            "directory": args.ftp_directory
        }
    monitor = SocialMediaActivityMonitor(
        log_dir=args.log_dir,
        ftp_config=ftp_config,
        interval=args.interval,
        iterations=args.iterations
    )
    monitor.start()

if __name__ == "__main__":
    main()

import os
import time
import logging
import socket
import http.client
import threading

# Configure logging
LOG_FILE = './usb_scanner.log'
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def list_usb_storage_devices():
    usb_devices = []
    mounts_file = '/proc/mounts'

    if os.path.exists(mounts_file):
        with open(mounts_file, 'r') as f:
            for line in f:
                parts = line.split()
                device, mount_point = parts[0], parts[1]
                if device.startswith('/dev/sd') and 'usb' in device.lower():
                    usb_devices.append((device, mount_point))
    return usb_devices

def collect_metadata(mount_point):
    metadata = []
    for root, _, files in os.walk(mount_point):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                stat = os.stat(file_path)
                file_info = {
                    'file_path': file_path,
                    'size': stat.st_size,
                    'creation_date': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(stat.st_ctime)),
                }
                metadata.append(file_info)
            except Exception as e:
                logging.error(f"Error collecting metadata for {file_path}: {e}")
                metadata.append({'file_path': file_path, 'error': str(e)})
    return metadata

def save_metadata_to_file(metadata, output_file):
    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    with open(output_file, 'w') as f:
        for entry in metadata:
            if 'error' in entry:
                f.write(f"Error reading file: {entry['file_path']} - {entry['error']}\n")
            else:
                f.write(f"File: {entry['file_path']}, Size: {entry['size']} bytes, Created: {entry['creation_date']}\n")

def send_metadata_to_server(metadata, server_url):
    try:
        conn = http.client.HTTPConnection(server_url)
        headers = {'Content-Type': 'application/json'}
        payload = str(metadata).replace("'", '"')  # Convert to JSON-like string
        conn.request("POST", "/upload", payload, headers)
        response = conn.getresponse()
        logging.info(f"Sent metadata to server {server_url}. Response: {response.status} {response.reason}")
        conn.close()
    except (socket.error, http.client.HTTPException) as e:
        logging.error(f"Failed to send metadata to server {server_url}: {e}")

def scan_and_process(output_file, server_url):
    usb_devices = list_usb_storage_devices()
    all_metadata = []

    if usb_devices:
        logging.info("Scanning USB storage devices...")
        for device, mount_point in usb_devices:
            logging.info(f"Collecting metadata for device {device} at mount point {mount_point}...")
            metadata = collect_metadata(mount_point)
            all_metadata.extend(metadata)
    else:
        logging.info("No USB storage devices detected.")

    save_metadata_to_file(all_metadata, output_file)
    logging.info(f"Metadata saved to {output_file}")

    send_metadata_to_server(all_metadata, server_url)

def register_as_service(interval=60, iterations=1, output_file='./target/output_file.txt', server_url='localhost:8000'):
    def service_task():
        for _ in range(iterations):
            scan_and_process(output_file, server_url)
            time.sleep(interval)

    service_thread = threading.Thread(target=service_task)
    service_thread.daemon = True
    service_thread.start()
    logging.info(f"Background service registered with interval={interval} seconds and iterations={iterations}.")

def main():
    output_file = './target/output_file.txt'
    server_url = 'localhost:8000'
    interval = 60
    iterations = 1

    # Run as service (optional)
    register_as_service(interval=interval, iterations=iterations, output_file=output_file, server_url=server_url)

    # Run a single scan immediately
    scan_and_process(output_file, server_url)

if __name__ == "__main__":
    main()

import os
import http.client

def read_file(input_path):
    if not os.path.exists(input_path):
        print(f"Error: File '{input_path}' does not exist.")
        return None

    try:
        with open(input_path, 'r') as infile:
            return infile.readlines()
    except OSError as e:
        print(f"Error: Unable to read the file '{input_path}'. {e}")
        return None

def write_file(output_path, lines):
    try:
        with open(output_path, 'w') as outfile:
            for line in lines:
                outfile.write(line)
        return True
    except OSError as e:
        print(f"Error: Unable to write to the file '{output_path}'. {e}")
        return False

def report_to_server(output_path):
    server = 'attendance.example.com'
    endpoint = '/report'

    try:
        with open(output_path, 'r') as file:
            data = file.read()

        connection = http.client.HTTPConnection(server)
        headers = {'Content-Type': 'text/plain'}
        connection.request('POST', endpoint, body=data, headers=headers)
        response = connection.getresponse()

        if response.status == 200:
            print(f"Successfully reported location records to the server: {server}")
        else:
            print(f"Failed to report to the server. HTTP Status: {response.status}, Reason: {response.reason}")
    except (OSError, http.client.HTTPException) as e:
        print(f"Error: Unable to report to the server. {e}")
    finally:
        if 'connection' in locals():
            connection.close()

def process_and_report():
    input_path = 'target/location.txt'
    output_path = 'location_log.txt'

    # Step 1: Read the input file
    lines = read_file(input_path)
    if lines is None:
        return

    # Step 2: Write the records to location_log.txt
    if not write_file(output_path, lines):
        return

    # Step 3: Report the records to the remote server
    report_to_server(output_path)

if __name__ == "__main__":
    process_and_report()

