def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def encrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = data.encode('utf-8')
    encrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return base64.b64encode(encrypted).decode('utf-8')

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

def collect_time_and_timezone_info():
    now = datetime.datetime.now()
    formatted_time = now.strftime("%Y-%m-%d %H:%M:%S")
    timezone = time.tzname[time.daylight]
    return {
        "timestamp": formatted_time,
        "system_time": formatted_time,
        "timezone": timezone
    }

def append_to_log_file(log_entry, passphrase):
    encrypted_entry = encrypt(json.dumps(log_entry), passphrase)
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(encrypted_entry + '\n')

def send_data_to_server(data, server_url):
    parsed_url = urllib.parse.urlparse(server_url)
    connection = http.client.HTTPConnection(parsed_url.netloc, timeout=10)
    headers = {'Content-Type': 'application/json'}
    body = json.dumps(data)
    connection.request("POST", parsed_url.path, body, headers)
    response = connection.getresponse()
    return response.status, response.read()

def retry_with_backoff(func, max_attempts, *args, **kwargs):
    for attempt in range(max_attempts):
        try:
            result = func(*args, **kwargs)
            return result
        except Exception as e:
            if attempt < max_attempts - 1:
                sleep(2 ** attempt)
            else:
                raise e

def write_config(interval, iterations):
    config = {
        "interval": interval,
        "iterations": iterations
    }
    with open(CONFIG_FILE, 'w') as config_file:
        config_file.write(json.dumps(config))

def read_config():
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, 'r') as config_file:
            return json.loads(config_file.read())
    return {"interval": DEFAULT_INTERVAL, "iterations": DEFAULT_ITERATIONS}

def write_recovery_instructions():
    instructions = """
    <html>
    <head><title>Decryption Instructions</title></head>
    <body>
        <h1>Log File Decryption Instructions</h1>
        <p>The log file <code>{log_file}</code> is encrypted. To decrypt it, use the following Python code:</p>
        <pre>
import hashlib
import base64

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

with open('{log_file}', 'r') as f:
    encrypted_lines = f.readlines()

passphrase = "your_passphrase_here"
for line in encrypted_lines:
    print(decrypt(line.strip(), passphrase))
        </pre>
        <p>Replace <code>your_passphrase_here</code> with the passphrase used to encrypt the file.</p>
    </body>
    </html>
    """.format(log_file=LOG_FILE)
    with open(INSTRUCTIONS_FILE, 'w') as file:
        file.write(instructions)

def run_service(server_url, passphrase, interval, iterations):
    for _ in range(iterations):
        log_entry = collect_time_and_timezone_info()
        append_to_log_file(log_entry, passphrase)
        try:
            retry_with_backoff(send_data_to_server, MAX_RETRIES, log_entry, server_url)
        except Exception as e:
            print(f"Failed to send data to server: {e}")
        if iterations > 1:
            sleep(interval)

if __name__ == "__main__":
    if not os.path.exists(INSTRUCTIONS_FILE):
        write_recovery_instructions()

    config = read_config()
    interval = config.get("interval", DEFAULT_INTERVAL)
    iterations = config.get("iterations", DEFAULT_ITERATIONS)

    user_passphrase = input("Enter passphrase (or press Enter to use default): ") or DEFAULT_PASSPHRASE
    server_url = input(f"Enter server URL (default: {DEFAULT_SERVER_URL}): ") or DEFAULT_SERVER_URL

    write_config(interval, iterations)
    run_service(server_url, user_passphrase, interval, iterations)

import os
import sys
import random
import time
from datetime import datetime

def generate_mock_location():
    latitude = random.uniform(-90.0, 90.0)
    longitude = random.uniform(-180.0, 180.0)
    return latitude, longitude

def append_location_to_file(file_path, latitude, longitude):
    try:
        with open(file_path, 'a') as f:
            f.write(f"\nLatitude: {latitude}, Longitude: {longitude}\n")
    except Exception as e:
        log_error(f"Unable to append location to file. Details: {e}")
        sys.exit(1)

def log_location(file_dir, latitude, longitude):
    log_file_path = os.path.join(file_dir, 'geo_log.txt')
    try:
        with open(log_file_path, 'a') as f:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            f.write(f"{timestamp} - Injected into file: Latitude: {latitude}, Longitude: {longitude}\n")
    except Exception as e:
        log_error(f"Unable to write to log file. Details: {e}")
        sys.exit(1)

def log_error(message):
    print(f"Error: {message}")

def validate_file(file_path):
    if os.path.isfile(file_path):
        print(f"File recognized: {file_path}")
        return True
    else:
        log_error(f"File does not exist or is not a valid file: {file_path}")
        return False

def service_execution(file_path, interval, cycles):
    file_dir = os.path.dirname(file_path)
    for cycle in range(cycles):
        latitude, longitude = generate_mock_location()
        append_location_to_file(file_path, latitude, longitude)
        log_location(file_dir, latitude, longitude)
        print(f"Cycle {cycle + 1}/{cycles}: Location injected - Latitude={latitude}, Longitude={longitude}")
        time.sleep(interval)

def main():
    if len(sys.argv) < 2:
        print("Usage: python validate_file.py <file_path> [--service] [--interval=<seconds>] [--cycles=<count>]")
        sys.exit(1)

    file_path = sys.argv[1]
    service_mode = '--service' in sys.argv
    interval = 10  # Default interval
    cycles = 1     # Default cycles

    for arg in sys.argv[2:]:
        if arg.startswith('--interval='):
            try:
                interval = int(arg.split('=')[1])
            except ValueError:
                log_error("Invalid interval value. Must be an integer.")
                sys.exit(1)
        elif arg.startswith('--cycles='):
            try:
                cycles = int(arg.split('=')[1])
            except ValueError:
                log_error("Invalid cycles value. Must be an integer.")
                sys.exit(1)

    if not validate_file(file_path):
        sys.exit(1)

    if service_mode:
        print(f"Running in service mode: interval={interval}s, cycles={cycles}")
        service_execution(file_path, interval, cycles)
    else:
        latitude, longitude = generate_mock_location()
        append_location_to_file(file_path, latitude, longitude)
        file_dir = os.path.dirname(file_path)
        log_location(file_dir, latitude, longitude)
        print(f"Location data injected: Latitude={latitude}, Longitude={longitude}")

if __name__ == "__main__":
    main()

