def perform_conversion(source_currency, target_currency, amount, exchange_rate, log_file):
    converted_amount = amount * exchange_rate
    print(f"{amount} {source_currency} is {converted_amount:.2f} {target_currency} (exchange rate: {exchange_rate})")
    log_conversion(source_currency, target_currency, amount, converted_amount, exchange_rate, log_file)

def run_service(source_currency, target_currency, amount, interval, cycles, exchange_rate, log_file):
    for _ in range(cycles):
