import os
import platform
import sys
import argparse
import logging

def setup_logging(verbose):
    logging_level = logging.DEBUG if verbose else logging.INFO
    logging.basicConfig(
        level=logging_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

def collect_system_info():
    try:
        return {
            "os": os.name,
            "version": platform.version(),
            "system": platform.system(),
        }
    except Exception as e:
        logging.error("Failed to collect system information: %s", str(e))
        raise

def write_system_info_to_file(info, filename):
    try:
        with open(filename, "w") as file:
            for key, value in info.items():
                file.write(f"{key}: {value}\n")
        logging.info("System information written to %s", filename)
    except Exception as e:
        logging.error("Failed to write system information to file: %s", str(e))
        raise

def parse_arguments():
    parser = argparse.ArgumentParser(description="System Info Report Tool")
    parser.add_argument(
        "-o", "--output",
        type=str,
        default="system_info.txt",
        help="Output file name (default: system_info.txt)"
    )
    parser.add_argument(
        "-v", "--verbose",
        action="store_true",
        help="Enable verbose output"
    )
    return parser.parse_args()

def main():
