import sys
import os

LOG_FILE = 'infect_log.txt'

def log_append_operation(data, file_path, log_level):
    log_entry = f"{log_level},{data},{len(data)},{file_path}\n"
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(log_entry)

def append_to_file(file_path, data, dry_run, print_success, log_level):
    if dry_run:
        if log_level == 'INFO':
            print(f"[DRY RUN] Simulated appending data to {file_path}, size: {len(data)} bytes.")
        return

    try:
        with open(file_path, 'a') as file:
            file.write(data)

        log_append_operation(data, file_path, log_level)

        if print_success and log_level == 'INFO':
            print("Data appended successfully.")
    except FileNotFoundError:
        print(f"ERROR: The file '{file_path}' does not exist.")
        sys.exit(1)
    except PermissionError:
        print(f"ERROR: Insufficient permissions to write to '{file_path}'.")
        sys.exit(1)
    except Exception as e:
        print(f"ERROR: An unexpected error occurred: {e}")
        sys.exit(1)

def summarize_log(summary_only):
    try:
        total_bytes = 0
        total_entries = 0

        if os.path.exists(LOG_FILE):
            with open(LOG_FILE, 'r') as log_file:
                for line in log_file:
                    _, _, byte_size, _ = line.strip().split(',')
                    total_bytes += int(byte_size)
                    total_entries += 1

        if not summary_only:
            print(f"Summary: {total_bytes} bytes appended, {total_entries} log entries written.")
        else:
            print(f"{total_bytes} bytes appended, {total_entries} log entries written.")
    except Exception as e:
        print(f"ERROR: An error occurred while summarizing logs: {e}")
        sys.exit(1)

def parse_flags(args):
    dry_run = '--dry-run' in args
    summary_only = '--summary-only' in args
    print_success = '--print-success' in args
    log_level = 'INFO' if '--log-level=INFO' in args else 'ERROR'
    args = [arg for arg in args if not arg.startswith('--')]
    return args, dry_run, summary_only, print_success, log_level

def main():
    args, dry_run, summary_only, print_success, log_level = parse_flags(sys.argv[1:])

    if len(args) < 2:
        print("Usage: python utility.py <file_path> <data> [--print-success] [--dry-run] [--summary-only] [--log-level=INFO|ERROR]")
        sys.exit(1)

    file_path = args[0]
    data = args[1]

    append_to_file(file_path, data, dry_run, print_success, log_level)
    summarize_log(summary_only)

if __name__ == '__main__':
    main()

import os
import stat
import sys
import hashlib
import time
from datetime import datetime

def is_executable(filepath):
    try:
        st = os.stat(filepath)
        return bool(st.st_mode & stat.S_IXUSR)
    except OSError:
        return False

def scan_directory_for_executables(directory):
    executable_files = []
    try:
        for root, _, files in os.walk(directory):
            for name in files:
                filepath = os.path.join(root, name)
                if is_executable(filepath):
                    executable_files.append(filepath)
    except Exception as e:
        log(f"Error scanning directory: {e}")
    return executable_files

def encrypt_file(input_file, output_file, key):
    try:
        with open(input_file, 'r') as f:
            data = f.read()
        encrypted_data = ''.join(chr(ord(c) ^ key[i % len(key)]) for i, c in enumerate(data))
        with open(output_file, 'w') as f:
            f.write(encrypted_data)
    except Exception as e:
        log(f"Error encrypting file: {e}")

